yakit.AutoInitYakit()

thread := cli.Int("thread")
wg := sync.NewSizedWaitGroup(thread)

targets = cli.String("targets")
slice := str.SplitAndTrim(targets, "\n")

# Input your code!
yakit.EnableTable("结果", ["domain", "IP", "CDN"])
outputTable = func(domain, IP, CDN) {
    data = make(map[string]var)
    data["domain"] = domain
    data["IP"] = IP
    data["CDN"] = CDN
    yakit.TableData("结果", data)
}


func req(domain) {
    wg.Add()

    go fn {
        defer wg.Done()


        CDN = "True"
        IP = "Error"
        for i in 10 {
            res = dns.QueryIPAll(domain)
            if len(res) >= 1 {
                IP = res[0]
                if len(res) == 1 {
                    CDN = "False"
                }

                break
            }

        }


        outputTable(domain, IP, CDN)
    }
}

for index, element = range slice {
    domain := element
    req(domain)
}


wg.Wait()
